initPhones() {
  const scales = Array.from(document.querySelectorAll('.tp-phone-scale'));
  const fit = () => scales.forEach((sc) => {
    const f = sc.querySelector('.tp-app-frame');
    if (!f) return;
    const w = sc.clientWidth;
    if (w > 0) f.style.transform = 'scale(' + (w / 390) + ')';
  });
