    const rimM = new THREE.MeshStandardMaterial({ color: 0x8ea9dd, metalness: 0.95, roughness: 0.3 });
    const capM = new THREE.MeshStandardMaterial({ color: 0x0a1035, metalness: 0.6, roughness: 0.55 });

    const group = new THREE.Group();

