this.initMobileLayout();
// ---- adaptive quality: device tier + live FPS governor ----
const mem = navigator.deviceMemory || 8, cores = navigator.hardwareConcurrency || 8;
let tier = 2;
if (mem <= 4 || cores <= 4 || window.innerWidth < 880) tier = 1;
if (mem <= 2 || cores <= 2) tier = 0;
this._tier = tier;
this._dprCap = [1, 1.5, 2][tier];
this._blurMax = [1.4, 2.4, 3.5][tier];
this._prSetters = [];

this.initPhone3D();
this.initPhones();
this.initCoins();

// stagger the app copies: primary phone right after first paint, secondary when near view
setTimeout(() => {
  const f = document.querySelector('iframe[data-late-src]');
  if (f && !f.getAttribute('src')) f.src = f.getAttribute('data-late-src');
}, 450);

